import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int[] primes = new int[600005]; int count = 0; int num = 2; while (count < 600005) { if (isPrime(num)) { primes[count++] = num; } num++; } int t = Integer.parseInt(br.readLine()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int m = Integer.parseInt(st.nextToken()); for (int i = 0; i < n; i++) { for (int j = 0; j < m; j++) { out.print(primes[i + j] + " "); } out.println(); } } out.flush(); out.close(); } private static boolean isPrime(int n) { if (n < 2) return false; for (int i = 2; i * i <= n; i++) { if (n % i == 0) return false; } return true; } }